// Pension Helper: checks one pensioner of ONE workspace (the backend sends {name, dataset}).
const DS = String($('Dashboard asks to check a pensioner').first().json.body?.dataset || '');
const WS = Object.fromEntries($('Get workspaces').all().map(i => i.json).filter(w => w.key).map(w => [w.key, w]));
const W = WS[DS] || {};
const mine = r => !!DS && /^w\d+$/.test(DS) && r.dataset === DS;
const DA_OLD = Number(W.da_old ?? 55);
const DA_NEW = Number(W.da_new ?? 58);
const DA_NEW_FROM = W.da_new_from || '2026-07';
const URGENT_DAYS = 7;

const zone = 'Asia/Kolkata';
const today = DateTime.now().setZone(zone).startOf('day');
const year = today.year;
const inr = (n) => '₹' + Math.round(n).toLocaleString('en-IN');
const monthLabel = (m) => DateTime.fromFormat(m, 'yyyy-MM').toFormat('LLLL yyyy');
const dayIn = v => v ? DateTime.fromISO(typeof v === 'string' ? v : new Date(v).toISOString()).setZone(zone).toISODate() : null;

const profile = $('Get pensioner profile').all().map(i => i.json).find(p => p.name && mine(p)) || {};
const requested = $('Read pensioner name').first().json.name;

if (!profile.name) {
  return [{ json: { found: false, name: requested, dataset: DS, needs_letter: false, issues: ['No pensioner found with this name.'], steps: [] } }];
}

const openMonth = profile.age >= 80 ? 10 : 11;
const openDate = DateTime.fromObject({ year, month: openMonth, day: 1 }, { zone });
const deadline = DateTime.fromObject({ year, month: 11, day: 30 }, { zone });
const daysLeft = Math.round(deadline.diff(today, 'days').days);
const verifiedUntil = dayIn(profile.lc_verified_until);
const submitted = !!verifiedUntil && verifiedUntil > deadline.toISODate();

let lcStatus;
if (submitted) lcStatus = 'done';
else if (today < openDate) lcStatus = 'not_open_yet';
else if (daysLeft < 0) lcStatus = 'missed';
else if (daysLeft <= URGENT_DAYS) lcStatus = 'urgent';
else lcStatus = 'open';

const lcText = {
  done: 'Verified until ' + (verifiedUntil ? DateTime.fromISO(verifiedUntil).toFormat('d LLLL yyyy') : '') + ' ✓ (Jeevan Pramaan ID ' + (profile.pramaan_id || '-') + '). Nothing to do this year.',
  not_open_yet: 'Submission window opens on ' + openDate.toFormat('d LLLL') + '.',
  open: 'Not submitted yet. ' + daysLeft + ' days left (deadline ' + deadline.toFormat('d LLLL') + ').',
  urgent: 'Not submitted yet. Only ' + daysLeft + ' days left! Deadline ' + deadline.toFormat('d LLLL') + '.',
  missed: 'Deadline missed. Pension may pause from December until it is submitted.'
}[lcStatus];
const lcLevel = { done: 'ok', not_open_yet: 'ok', open: 'warning', urgent: 'alert', missed: 'alert' }[lcStatus];

const rows = $('Get pension payments').all().map(i => i.json).filter(r => r.month && r.name === profile.name && mine(r)).sort((a, b) => (a.month < b.month ? -1 : 1));
const payments = rows.map(r => {
  const da = r.month >= DA_NEW_FROM ? DA_NEW : DA_OLD;
  const expected = Math.round(r.basic_pension * (1 + da / 100) - (r.commuted_amount || 0));
  const received = Number(r.amount_received) || 0;
  const difference = expected - received;
  let status = 'ok';
  if (received === 0) status = 'missing';
  else if (difference > 0) status = 'short';
  return { month: r.month, month_label: monthLabel(r.month), da_percent: da, expected, received, difference, status };
});

const problems = payments.filter(p => p.status !== 'ok');
const amountShort = problems.reduce((s, p) => s + p.difference, 0);
const issues = [];
if (lcLevel !== 'ok') issues.push(lcText);
problems.forEach(p => {
  if (p.status === 'missing') issues.push('No pension credited for ' + p.month_label + ' (' + inr(p.expected) + ' expected).');
  else issues.push(p.month_label + ': paid ' + inr(p.received) + ' instead of ' + inr(p.expected) + ' (short by ' + inr(p.difference) + ').');
});

const paymentStatus = payments.length === 0 ? 'no_data' : (problems.length ? 'problem' : 'ok');
const paymentText = payments.length === 0
  ? 'No bank statement data found.'
  : problems.length
    ? problems.length + ' problem month(s) found. Total missing: ' + inr(amountShort) + '.'
    : 'All ' + payments.length + ' payments arrived in full.';

const problemLines = problems.map(p => '- ' + p.month_label + ': expected ' + inr(p.expected) + ', received ' + inr(p.received) + ', difference ' + inr(p.difference)).join('\n');
const templateLetter = 'To,\nThe Branch Manager / Pension Cell,\n' + profile.bank + '\n\n'
  + 'Subject: Request to release pending pension amount – PPO ending ' + profile.ppo_last4 + '\n\n'
  + 'Respected Sir/Madam,\n\n'
  + 'I, ' + profile.name + ', am a pensioner drawing my pension through your bank (PPO number ending ' + profile.ppo_last4 + '). '
  + 'On checking my bank statement, I found the following issues with my pension credits:\n\n'
  + problemLines + '\n\n'
  + 'Total amount pending: ' + inr(amountShort) + '.\n\n'
  + 'I kindly request you to look into this and release the pending amount at the earliest. '
  + 'I will be happy to provide any documents you need.\n\n'
  + 'Thanking you,\n\n' + profile.name + '\nSignature: ____________\nDate: ____________';

return [{
  json: {
    found: true,
    dataset: DS,
    checked_at: DateTime.now().setZone(zone).toISO(),
    pensioner: { name: profile.name, age: profile.age, bank: profile.bank, ppo_last4: profile.ppo_last4, language: profile.language, family_email: profile.family_email },
    life_certificate: {
      status: lcStatus, level: lcLevel, days_left: daysLeft, submitted,
      verified_until: submitted ? verifiedUntil : null, pramaan_id: submitted ? (profile.pramaan_id || null) : null,
      window_opens: openDate.toFormat('d LLLL yyyy'), deadline: deadline.toFormat('d LLLL yyyy'), message: lcText
    },
    payment_check: { status: paymentStatus, message: paymentText, amount_short: amountShort, months: payments },
    steps: [
      { key: 'deadline', title: 'Life certificate check', level: lcLevel, detail: lcText },
      { key: 'payments', title: 'Pension payment check', level: paymentStatus === 'problem' ? 'alert' : 'ok', detail: paymentText }
    ],
    issues,
    issues_count: issues.length,
    needs_letter: problems.length > 0,
    problem_summary: problemLines,
    template_letter: templateLetter
  }
}];

